select pg_temp.check_ok((select price=100 from gf_items where id='frame-ember') and (select price=300 from gf_items where id='theme-copper'),'legacy prices unchanged');
select buy_cosmetic('frame-energy','UTC');
select buy_cosmetic('share-impact','UTC');
select buy_cosmetic('theme-progress','UTC');
select buy_cosmetic('emoji-fire','UTC');
select buy_cosmetic('emoji-fire','Pacific/Kiritimati');
select pg_temp.check_ok((select balance=270 from coin_wallets where user_id=auth.uid()),'server prices and duplicate-safe emoji purchase');
select pg_temp.check_ok((select count(*)=4 from gf_inventory where user_id=auth.uid()),'four permanent categories');
select equip_cosmetic('frame','frame-energy','UTC');
select equip_cosmetic('share','share-impact','UTC');
select equip_cosmetic('theme','theme-progress','UTC');
select equip_cosmetic('emoji','emoji-fire','UTC');
select pg_temp.check_ok((select count(*)=4 from gf_equipped where user_id=auth.uid()),'equip every category');
select pg_temp.check_ok((select count(*)=4 from jsonb_array_elements(gf_shop_catalog_state(auth.uid())) i where (i->>'equipped')::boolean),'equipment persists when reloaded');
select equip_cosmetic('emoji',null,'UTC');
select pg_temp.check_ok((select count(*)=4 from gf_inventory where user_id=auth.uid()),'unequip keeps permanent inventory');
do $$ begin
 begin perform buy_cosmetic('frame-champion','UTC');raise exception 'locked bought';exception when raise_exception then if sqlerrm='locked bought' then raise;end if;end;
 begin perform equip_cosmetic('frame','emoji-fire','UTC');raise exception 'wrong category';exception when raise_exception then if sqlerrm='wrong category' then raise;end if;end;
end $$;
insert into gf_badges(user_id,key,historical) values(auth.uid(),'week-4',true);
select buy_cosmetic('frame-champion','UTC');
select pg_temp.check_ok((select balance=20 from coin_wallets where user_id=auth.uid()),'existing badge prerequisite unlocks existing price');
do $$ begin begin perform buy_cosmetic('emoji-rocket','UTC');raise exception 'negative balance';exception when raise_exception then if sqlerrm='negative balance' then raise;end if;end;end $$;
select pg_temp.check_ok((select balance=20 from coin_wallets where user_id=auth.uid()),'insufficient balance leaves wallet intact');
insert into streak_groups(id,owner_id,name,time_zone,status,started_on) values('26000000-0000-4000-8000-000000000001',auth.uid(),'Fixture reactions','UTC','active',current_date);
insert into group_members(group_id,user_id,status) select '26000000-0000-4000-8000-000000000001',id,'accepted' from auth.users where id in(auth.uid(),'a0000000-0000-4000-8000-000000000002');
insert into workout_days(user_id,day,activity,minutes) values('a0000000-0000-4000-8000-000000000002',current_date,'Fixture walk',35);
select set_group_reaction('26000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002','emoji-fire');
select set_group_reaction('26000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002','emoji-fire');
select pg_temp.check_ok((select count(*)=1 from group_workout_reactions),'idempotent reaction');
select pg_temp.check_ok((get_group_reactions('26000000-0000-4000-8000-000000000001')->0->>'count')::integer=1,'persisted group reaction count');
select pg_temp.check_ok((select balance=20 from coin_wallets where user_id=auth.uid()),'reactions grant no coins');
do $$ begin
 begin perform set_group_reaction('26000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002','emoji-rocket');raise exception 'unowned emoji';exception when raise_exception then if sqlerrm='unowned emoji' then raise;end if;end;
 begin perform set_group_reaction('26000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002','frame-energy');raise exception 'nonemoji accepted';exception when raise_exception then if sqlerrm='nonemoji accepted' then raise;end if;end;
 begin perform set_group_reaction('26000000-0000-4000-8000-000000000001',auth.uid(),'emoji-fire');raise exception 'unconfirmed workout';exception when raise_exception then if sqlerrm='unconfirmed workout' then raise;end if;end;
end $$;
select set_group_reaction('26000000-0000-4000-8000-000000000001','a0000000-0000-4000-8000-000000000002',null);
select pg_temp.check_ok((select count(*)=0 from group_workout_reactions),'remove own reaction');
set request.jwt.claim.sub='a0000000-0000-4000-8000-000000000003';
do $$ begin begin perform get_group_reactions('26000000-0000-4000-8000-000000000001');raise exception 'outsider read';exception when raise_exception then if sqlerrm='outsider read' then raise;end if;end;end $$;
select pg_temp.check_ok(not has_table_privilege('authenticated','group_workout_reactions','SELECT,INSERT,UPDATE,DELETE') and (select relrowsecurity from pg_class where oid='group_workout_reactions'::regclass),'RLS and no direct access');
select pg_temp.check_ok(not has_function_privilege('anon','get_group_reactions(uuid)','EXECUTE') and not has_function_privilege('anon','set_group_reaction(uuid,uuid,text)','EXECUTE'),'authentication required');
select pg_temp.check_ok(not exists(select 1 from jsonb_array_elements(gf_shop_catalog_state(auth.uid())) i where (i->>'owned')::boolean),'inventory account isolation');
select pg_temp.check_ok(jsonb_array_length(gf_cosmetics_state(auth.uid()))=6,'legacy PWA catalog remains compatible');
select pg_temp.check_ok((select count(*)=11 from jsonb_array_elements(get_gamification_state('UTC',2)->'cosmetics') i where i->>'category'='emoji'),'new authenticated catalog exposes functional emojis');
select 'PASS shop expansion: catalog, prices, four categories, ownership, equipment, achievements, insufficient funds, reactions, isolation';
